"""Сборка статической HTML-страницы из data/checklists.json.

Дизайн повторяет исходный артефакт (светлая тема, Golos Text, сайдбар встреч,
карточки по дизайнерам, теги, зелёные чекбоксы, localStorage) и добавляет режим
«Дизайнеры»: выбираешь дизайнера — видишь только его правки по всем встречам.

Страница самодостаточна (один index.html), хостится где угодно.
"""
import html
import json
from datetime import datetime

from . import config

RU_MONTHS = ["января", "февраля", "марта", "апреля", "мая", "июня",
             "июля", "августа", "сентября", "октября", "ноября", "декабря"]

CSS = """
* { box-sizing: border-box; margin: 0; padding: 0; }
html { height: 100%; }
/* Фон страницы чёрный — под стать иллюстрациям. Скроллится не страница,
   а содержимое белой рабочей области, поэтому у body скролла нет вовсе. */
body { background: #000; font-family: 'Golos Text', sans-serif; font-size: 15px; line-height: 1.5; height: 100%; overflow: hidden; display: flex; color: #1a1a1a; }
.sidebar { width: 250px; flex-shrink: 0; background: transparent; padding: 24px 0; display: flex; flex-direction: column; position: fixed; top: 0; left: 0; bottom: 0; overflow-y: auto; }
/* Переключатель режимов: белая плашка, выбранная вкладка — чёрная внутри неё. */
.mode-toggle { display: flex; gap: 2px; margin: 0 16px 18px; background: #fff; border-radius: 999px; padding: 4px; }
.mode-btn { flex: 1; text-align: center; font-size: 14px; font-weight: 600; padding: 7px 8px; border-radius: 999px; cursor: pointer; color: #8A8A90; border: none; background: transparent; font-family: inherit; transition: all .12s; }
.mode-btn:hover { color: #1a1a1a; }
.mode-btn.active { background: #000; color: #fff; }
.sidebar-title { font-size: 11px; font-weight: 600; letter-spacing: 0.08em; text-transform: uppercase; color: #6E6E73; padding: 0 20px; margin-bottom: 12px; }
.nav-item { margin: 1px 16px; padding: 8px 4px; cursor: pointer; transition: color .12s; }
.nav-item:hover .nav-main { color: #E4E4E8; }
/* Выбранный пункт ничем не обведён — его подсвечивает сам текст,
   тем же зелёным, что и корона рядом. */
.nav-item.active .nav-main { color: #A7F902; }
.nav-item.active .nav-sub { color: rgba(167,249,2,.55); }
.nav-main { font-size: 14px; font-weight: 600; color: #F2F2F4; }
.nav-item:not(.active) .nav-main { color: #9A9AA2; font-weight: 500; }
.nav-sub { font-size: 12px; color: #6E6E73; margin-top: 1px; }
.nav-empty { padding: 10px 20px; color: #6E6E73; font-size: 13px; }
.nav-divider { height: 1px; background: rgba(255,255,255,.12); margin: 12px 16px 10px; }
/* Белая рабочая область — цельная карточка с одинаковыми полями со всех
   четырёх сторон. Снизу она не упирается в край экрана: вместо страницы
   скроллится её собственное содержимое. */
.main { position: fixed; top: 8px; right: 8px; bottom: 8px; left: 250px; margin: 0; background: #fff; border-radius: 24px; padding: 40px; overflow-y: auto; overscroll-behavior: contain; }
/* Сайдбар скроллится, но полоску не показывает — на чёрном фоне она лишняя. */
.sidebar { scrollbar-width: none; -ms-overflow-style: none; }
.sidebar::-webkit-scrollbar { width: 0; height: 0; display: none; }
.main::-webkit-scrollbar { width: 8px; }
.main::-webkit-scrollbar-track { background: transparent; }
.main::-webkit-scrollbar-thumb { background: #DCE1E7; border-radius: 999px; }
.main-inner { max-width: 800px; }
/* у последнего блока гасим собственный отступ, чтобы снизу осталось ровно
   то же поле карточки, что и сверху */
.main-inner > :last-child { margin-bottom: 0; }
.session-header { margin-bottom: 28px; }
.session-meta { font-size: 12px; color: #999; margin-bottom: 6px; letter-spacing: 0.04em; }
h1 { font-size: 60px; font-weight: 600; color: #1a1a1a; letter-spacing: -0.02em; line-height: 1.05; }
.crown svg { height: 19px; width: auto; vertical-align: middle; margin-left: 6px; position: relative; top: -2px; }
.crown-h1 svg { height: 56px; width: auto; vertical-align: baseline; margin-left: 14px; position: relative; top: 8px; }
.status-badge { display: inline-block; margin-top: 14px; font-size: 12px; font-weight: 600; color: #fff; padding: 5px 13px; border-radius: 999px; }
.st-king { background: #1a1a1a; }
.st-product { background: #9b59b6; }
.st-dev { background: #3a7be0; }
.st-seo { background: #2e9e6b; }
.st-legal { background: #9a7b2e; }
.st-brand { background: #d6336c; }
.st-rare { background: #8a94a6; }
.st-regular { background: #5a78b0; }
.st-ux { background: #199AF0; }
.st-second { background: #7E8BA3; }
.st-multi { background: #2BA39A; }
/* Номинации встречи: четыре вертикальные карточки в ряд.
   Иллюстрации нарочно вылезают за верхний край карточки — как в макете,
   поэтому у сетки большой отступ сверху, а место под картинку в потоке
   занимает пустая коробка .fun-icon фиксированной высоты. */
.fun-grid { display: grid; grid-template-columns: repeat(4, 1fr); gap: 12px; margin: 76px 0 22px; }
.fun-card { position: relative; background: #fff; border: 1px solid #E8ECF1; border-radius: 20px; padding: 20px 18px; display: flex; flex-direction: column; }
.fun-icon { position: relative; height: 44px; margin-bottom: 16px; }
.fun-icon svg { position: absolute; display: block; }
/* Размеры и сдвиги сняты с макета: картинка висит на нижнем крае коробки и уходит вверх за карточку. */
.fun-icon-weird_word svg { left: -5px; bottom: -4px; width: 100px; height: 119px; }
.fun-icon-catch_phrase svg { left: 18px; bottom: 0; width: 108px; height: 133px; }
.fun-icon-smart_comment svg { left: 18px; bottom: -13px; width: 153px; height: 138px; }
.fun-icon-filler_word svg { left: 35px; bottom: -6px; width: 106px; height: 135px; }
.fun-label { font-size: 10px; font-weight: 600; letter-spacing: 0.06em; text-transform: uppercase; color: #a7b0bd; margin-bottom: 8px; }
.fun-text { font-size: 15px; font-weight: 600; color: #1a1a1a; line-height: 1.35; }
/* умная мысль длиннее слова или фразы — ей свой кегль, чтобы влезала целиком */
.fun-text.long { font-size: 13px; font-weight: 500; line-height: 1.45; }
.fun-text.longer { font-size: 12px; font-weight: 500; line-height: 1.5; }
.fun-list { display: flex; flex-direction: column; gap: 7px; }
.fun-row { display: flex; align-items: baseline; justify-content: space-between; gap: 8px; }
.fun-word { font-size: 14px; font-weight: 600; color: #1a1a1a; }
.fun-num { font-size: 12px; color: #a7b0bd; white-space: nowrap; }
.fun-total { font-size: 12px; color: #a7b0bd; margin-top: auto; padding-top: 14px; }
.fun-context { font-size: 12px; color: #a7b0bd; line-height: 1.4; margin-top: 8px; }
.fun-meta { font-size: 12px; color: #a7b0bd; margin-top: auto; padding-top: 14px; }
.card-date { font-size: 12px; font-weight: 600; color: #999; margin: 22px 0 8px 2px; }
.card-date:first-child { margin-top: 0; }
.project { background: #fff; border: 1px solid #E8ECF1; border-radius: 20px; margin-bottom: 14px; overflow: hidden; }
.project-header { padding: 18px 20px; display: flex; align-items: center; justify-content: space-between; cursor: pointer; user-select: none; gap: 12px; }
.project-header:hover { background: #F6F8FA; }
.author { font-size: 15px; font-weight: 600; color: #1a1a1a; }
.project-name { font-size: 13px; color: #999; margin-top: 1px; }
.project-right { display: flex; align-items: center; gap: 12px; flex-shrink: 0; }
.count { font-size: 13px; color: #bbb; font-weight: 500; }
.count.done { color: #E10D87; }
.chevron { color: #ccc; font-size: 11px; transition: transform 0.2s; }
.project.collapsed .chevron { transform: rotate(-90deg); }
.project.collapsed .tasks { display: none; }
.tasks { border-top: 1px solid #EEF1F4; }
.task { display: flex; align-items: flex-start; gap: 12px; padding: 14px 20px; border-bottom: 1px solid #EEF1F4; cursor: pointer; }
.task:last-child { border-bottom: none; }
.task:hover { background: #F6F8FA; }
.checkbox { width: 17px; height: 17px; border-radius: 4px; border: 1.5px solid #CFD6DE; flex-shrink: 0; margin-top: 2px; display: flex; align-items: center; justify-content: center; transition: all .15s; background: #fff; }
.task.checked .checkbox { background: #C6F707; border-color: #C6F707; }
.task.checked .checkbox::after { content: ''; width: 4px; height: 8px; border: solid #000; border-width: 0 2px 2px 0; transform: rotate(45deg); margin-top: -2px; }
.task-text { font-size: 14px; color: #333; flex: 1; padding-top: 1px; }
.task.checked .task-text { color: #bbb; text-decoration: line-through; text-decoration-color: #ccc; }
.tag { display: inline-block; font-size: 10px; font-weight: 600; letter-spacing: 0.05em; padding: 2px 6px; border-radius: 4px; text-transform: uppercase; margin-left: 6px; vertical-align: middle; position: relative; top: -1px; }
.tag.ux { color: #e07b3a; background: #fef0e6; }
.tag.dev { color: #3a7be0; background: #e6effe; }
.tag.discuss { color: #9b59b6; background: #f5edfc; }
.tag.product { color: #9b59b6; background: #f5edfc; }
.tag.seo { color: #2e9e6b; background: #e6f7ee; }
.tag.legal { color: #9a7b2e; background: #f6efdc; }
.tag.branding { color: #d6336c; background: #fde8ef; }
.placeholder { color: #bbb; text-align: center; padding: 80px 20px; }
.reset-btn { position: fixed; bottom: 24px; right: 24px; background: #fff; border: 1px solid #E2E7EC; color: #999; font-family: 'Golos Text', sans-serif; font-size: 12px; padding: 8px 14px; border-radius: 8px; cursor: pointer; transition: all .15s; }
.reset-btn:hover { color: #555; border-color: #bbb; }
@media (max-width: 1000px) {
  /* в два столбца картинкам верхнего ряда нужен зазор, иначе они лягут на карточку выше */
  .fun-grid { grid-template-columns: repeat(2, 1fr); row-gap: 76px; }
}
@media (max-width: 640px) {
  /* на узком экране карточка снова тянется по содержимому, скроллит страница */
  body { flex-direction: column; height: auto; overflow: auto; }
  .sidebar { width: 100%; position: static; padding: 12px 0; border-radius: 0; }
  .mode-toggle { margin: 0 12px 10px; }
  .sidebar-title { display: none; }
  #nav-list { display: flex; overflow-x: auto; gap: 4px; padding: 0 8px; }
  .nav-item { flex-shrink: 0; border-left: none; border-bottom: 2px solid transparent; padding: 6px 10px; }
  .main { position: static; margin: 8px; padding: 24px 16px; overflow: visible; border-radius: 20px; }
  .fun-grid { grid-template-columns: 1fr; row-gap: 76px; }
  h1 { font-size: 38px; }
}
"""

